-- The Forge store, moved out of a JSON file and into the database.
--
-- Tasks, asset aliases, model enablement and the embedding cache lived in a
-- file written by the process that served the request. On Workers there is no
-- such file and no such process: each isolate had its own copy, so an image
-- generated by one was an "Unknown or expired asset id" to the next.
--
-- Each row keeps the full object as JSON alongside the few columns worth
-- filtering and sorting on. The shapes are defined in @sequel/core and change
-- with it; duplicating every field here would be a second schema to migrate.

CREATE TABLE IF NOT EXISTS task (
  id TEXT PRIMARY KEY,
  organization_id TEXT,
  created_by_user_id TEXT,
  model TEXT NOT NULL,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  data TEXT NOT NULL
);

-- The list is always newest-first, usually for one organisation.
CREATE INDEX IF NOT EXISTS task_created_at ON task (created_at DESC);
CREATE INDEX IF NOT EXISTS task_org_created_at ON task (organization_id, created_at DESC);
CREATE INDEX IF NOT EXISTS task_status ON task (status);

CREATE TABLE IF NOT EXISTS asset_alias (
  id TEXT PRIMARY KEY,
  data TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS model_state (
  id TEXT PRIMARY KEY,
  enabled INTEGER NOT NULL
);

-- Keyed by model id; the hash decides whether the vector still describes the
-- text it was made from.
CREATE TABLE IF NOT EXISTS embedding (
  id TEXT PRIMARY KEY,
  hash TEXT NOT NULL,
  model TEXT NOT NULL,
  vector TEXT NOT NULL
);
